import sys

MOD = 1000000007

def main():
    import sys
    import sys
    n, k, d = map(int, sys.stdin.read().split())
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(n + 1):
            for w in range(1, k + 1):
                if i - w >= 0:
                    dp[i][j] = (dp[i][j] + dp[i - w][j]) % MOD
                    if w >= d:
                        dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD

    result = (dp[n][n] - dp[n][n - 1]) % MOD
    print(result)

main()
